11	export type ScenarioResult = {
12	  results: { premium: number }[];
13	};
14	
15	const PROCESSING_FEE = 5;
16	
17	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
18	
19	const BASE_PREMIUMS: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	  rune: 25,
25	  moonstone: 25,
26	};
27	
28	// Percentages stay in integer percent points: multiply first, divide by 100
29	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
30	// a sword and breaks the ceil. `(base * 110) / 100` gives exactly 110.
31	const increasedBy = (amount: number, percent: number): number =>
32	  (amount * (100 + percent)) / 100;
33	
34	const percentOf = (amount: number, percent: number): number =>
35	  (amount * percent) / 100;
36	
37	const BLOCK_SIZE = 3;
38	const BLOCK_BASE_PREMIUM = 60;
39	
40	const countByType = (items: Item[]): Map<string, number> => {
41	  const counts = new Map<string, number>();
42	
43	  for (const item of items) {
44	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
45	  }
46	
47	  return counts;
48	};
49	
50	const baseOfGroup = (type: string, count: number): number =>
51	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
52	
53	const policyBaseOf = (items: Item[]): number =>
54	  [...countByType(items)].reduce(
55	    (total, [type, count]) => total + baseOfGroup(type, count),
56	    0,
57	  );
58	
59	const withFirstInsuranceSurcharge = (policyBase: number): number =>
60	  increasedBy(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
61	
62	const CURSE_SURCHARGE_PERCENT = 50;
63	
64	// Item-specific modifiers are charged on the item's own base premium and
65	// summed alongside the policy-wide ones — they do not compound.
66	const itemSurchargesOf = (items: Item[]): number =>
67	  items.reduce(
68	    (total, item) =>
69	      total +
70	      (item.cursed
71	        ? percentOf(BASE_PREMIUMS[item.type], CURSE_SURCHARGE_PERCENT)
72	        : 0),
73	    0,
74	  );
75	
76	const quote = (items: Item[]): number => {
77	  const policyBase = policyBaseOf(items);
78	  const surcharged =
79	    withFirstInsuranceSurcharge(policyBase) + itemSurchargesOf(items);
80	
81	  // Rounding is in the MHPCO's favour: premiums round up.
82	  return Math.ceil(surcharged) + PROCESSING_FEE;
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResult => ({
86	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
87	});
