// Policy-wide modifiers: each is a percentage of the policy base premium.
const policyModifiersOf = (policyBase: number): number =>
  percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);

const CURSE_SURCHARGE_PERCENT = 50;

// Item-specific modifiers: each is a percentage of the affected item's own
// base premium.
const itemModifiersOf = (item: Item): number =>
  item.cursed ? percentOf(BASE_PREMIUMS[item.type], CURSE_SURCHARGE_PERCENT) : 0;

const quote = (items: Item[]): number => {
  const policyBase = policyBaseOf(items);
  const modifiers =
    policyModifiersOf(policyBase) +
    items.reduce((total, item) => total + itemModifiersOf(item), 0);

  // Rounding is in the MHPCO's favour: premiums round up.
  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
};
